import CryptoKit
import Foundation
import Testing
@testable import PhotoCore

/// Cross-checks the `Sources/PhotoCore/AdobeProfile/` port against fixtures
/// generated by the Python prototype
/// (`.photobench/engine-research-20260922/dcp-base-prototype/scripts/run_all.py`,
/// header-offset-corrected per `CORRECTION.md`) in `Tests/Fixtures/phase1/`,
/// plus a handful of self-contained property tests that need no external
/// asset.
///
/// Tests that need the real "Panasonic DC-S5 Adobe Standard.dcp" / "Adobe
/// Color.xmp" assets (never checked into this repo -- see
/// `AdobeProfileLocator`) skip gracefully (early `return`, no
/// `Issue.record`) with a printed reason when those assets are not
/// installed on the machine running the tests.
struct AdobeProfileTests {
    // MARK: - Fixture loading

    private var projectRoot: URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent() // AdobeProfileTests.swift -> PhotoCoreTests/
            .deletingLastPathComponent() // -> Tests/
            .deletingLastPathComponent() // -> repo root
    }

    private func fixtureURL(_ name: String) -> URL {
        projectRoot.appendingPathComponent("Tests/Fixtures/phase1/\(name)")
    }

    private func loadFixture<T: Decodable>(_ name: String, as type: T.Type) throws -> T {
        let data = try Data(contentsOf: fixtureURL(name))
        return try JSONDecoder().decode(T.self, from: data)
    }

    // MARK: - Real-asset loading (skips gracefully when unavailable)

    private func loadRealDCP() -> DCPProfile? {
        guard let located = AdobeProfileLocator().locateDCP(uniqueCameraModel: "Panasonic DC-S5") else {
            print("SKIP: Panasonic DC-S5 Adobe StandardのDCPが見つからないため、この環境ではスキップします。")
            return nil
        }
        return located.profile
    }

    private func loadRealAdobeLook() -> AdobeLookXMP? {
        guard let url = AdobeProfileLocator().locateAdobeColorLookXMP() else {
            print("SKIP: Adobe Color.xmpが見つからないため、この環境ではスキップします。")
            return nil
        }
        return try? AdobeLookXMP(contentsOf: url)
    }

    // MARK: - Numeric comparison helpers

    private func approxEqual(_ a: Double, _ b: Double, relTol: Double, absTol: Double) -> Bool {
        if abs(a - b) <= absTol { return true }
        return abs(a - b) <= relTol * max(abs(a), abs(b))
    }

    private func expectApproxEqual(
        _ a: Double, _ b: Double, relTol: Double = 1e-3, absTol: Double = 1e-5, _ tag: String = ""
    ) {
        #expect(approxEqual(a, b, relTol: relTol, absTol: absTol), "\(tag) \(a) vs \(b)")
    }

    private func expectVectorApproxEqual(
        _ actual: SIMD3<Double>, _ expected: [Double], relTol: Double = 1e-3, absTol: Double = 1e-5,
        _ tag: String = ""
    ) {
        expectApproxEqual(actual.x, expected[0], relTol: relTol, absTol: absTol, "\(tag).x")
        expectApproxEqual(actual.y, expected[1], relTol: relTol, absTol: absTol, "\(tag).y")
        expectApproxEqual(actual.z, expected[2], relTol: relTol, absTol: absTol, "\(tag).z")
    }

    private func expectMatrixApproxEqual(
        _ actual: Matrix3x3, _ expectedRows: [[Double]], relTol: Double = 1e-4, absTol: Double = 1e-6,
        _ tag: String = ""
    ) {
        for r in 0..<3 {
            for c in 0..<3 {
                expectApproxEqual(actual[r, c], expectedRows[r][c], relTol: relTol, absTol: absTol, "\(tag)[\(r)][\(c)]")
            }
        }
    }

    private func expectHueSatSamplesMatch(
        _ table: DCPProfile.HueSatTable, _ samples: [HueSatSampleFixture], _ tag: String = ""
    ) {
        for sample in samples {
            let entry = table[sample.val_index, sample.hue_index, sample.sat_index]
            expectApproxEqual(entry.hueShift, sample.hue_shift, relTol: 1e-4, absTol: 1e-6, "\(tag) hueShift")
            expectApproxEqual(entry.satScale, sample.sat_scale, relTol: 1e-4, absTol: 1e-6, "\(tag) satScale")
            expectApproxEqual(entry.valScale, sample.val_scale, relTol: 1e-4, absTol: 1e-6, "\(tag) valScale")
        }
    }

    // MARK: - DCPProfile vs. dcp-panasonic-dc-s5.json

    @Test func dcpTagsAndSamplesMatchFixture() throws {
        guard let dcp = loadRealDCP() else { return }
        let fx = try loadFixture("dcp-panasonic-dc-s5.json", as: DCPFixtureFile.self)

        #expect(dcp.uniqueCameraModel == fx.unique_camera_model)
        #expect(dcp.profileName == fx.profile_name)
        #expect(dcp.calibrationIlluminant1 == fx.calibration_illuminant1)
        #expect(dcp.calibrationIlluminant2 == fx.calibration_illuminant2)
        #expect(dcp.hueSatMapEncoding == fx.hue_sat_map_encoding)
        #expect(dcp.lookTableEncoding == fx.look_table_encoding)
        #expect(dcp.hueSatMapDims == DCPProfile.Dimensions3(
            hue: fx.hue_sat_map_dims_hue_sat_val[0],
            sat: fx.hue_sat_map_dims_hue_sat_val[1],
            val: fx.hue_sat_map_dims_hue_sat_val[2]
        ))
        #expect(dcp.lookTableDims == DCPProfile.Dimensions3(
            hue: fx.look_table_dims_hue_sat_val[0],
            sat: fx.look_table_dims_hue_sat_val[1],
            val: fx.look_table_dims_hue_sat_val[2]
        ))

        if let m = dcp.colorMatrix1 { expectMatrixApproxEqual(m, fx.color_matrix1, "colorMatrix1") }
        else { Issue.record("ColorMatrix1が読めていません") }
        if let m = dcp.colorMatrix2 { expectMatrixApproxEqual(m, fx.color_matrix2, "colorMatrix2") }
        else { Issue.record("ColorMatrix2が読めていません") }
        if let m = dcp.forwardMatrix1 { expectMatrixApproxEqual(m, fx.forward_matrix1, "forwardMatrix1") }
        else { Issue.record("ForwardMatrix1が読めていません") }
        if let m = dcp.forwardMatrix2 { expectMatrixApproxEqual(m, fx.forward_matrix2, "forwardMatrix2") }
        else { Issue.record("ForwardMatrix2が読めていません") }

        if let t = dcp.hueSatMapData1 { expectHueSatSamplesMatch(t, fx.hue_sat_map_data1_samples, "huesat1") }
        else { Issue.record("HueSatMapData1が読めていません") }
        if let t = dcp.hueSatMapData2 { expectHueSatSamplesMatch(t, fx.hue_sat_map_data2_samples, "huesat2") }
        else { Issue.record("HueSatMapData2が読めていません") }
        if let t = dcp.lookTableData { expectHueSatSamplesMatch(t, fx.look_table_samples, "dcpLook") }
        else { Issue.record("LookTableDataが読めていません") }
    }

    // MARK: - AdobeLookXMP vs. adobe-color-look.json

    @Test func adobeLookMatchesFixture() throws {
        guard let look = loadRealAdobeLook() else { return }
        let fx = try loadFixture("adobe-color-look.json", as: AdobeLookFixtureFile.self)

        #expect(look.lookTableID.caseInsensitiveCompare(fx.look_table_id) == .orderedSame)
        #expect(look.lookTableID.caseInsensitiveCompare(fx.inflated_md5) == .orderedSame)
        #expect(look.headerType == fx.header_type)
        #expect(look.headerVersion == fx.header_version)
        #expect(look.dims == DCPProfile.Dimensions3(
            hue: fx.dims_hue_sat_val[0], sat: fx.dims_hue_sat_val[1], val: fx.dims_hue_sat_val[2]
        ))

        expectHueSatSamplesMatch(look.lookTableData, fx.samples, "adobeLook")

        #expect(look.toneCurvePoints.count == fx.tone_curve_points_0_255.count)
        for (point, expected) in zip(look.toneCurvePoints, fx.tone_curve_points_0_255) {
            expectApproxEqual(point.x, expected[0], relTol: 1e-6, absTol: 1e-9, "toneCurve.x")
            expectApproxEqual(point.y, expected[1], relTol: 1e-6, absTol: 1e-9, "toneCurve.y")
        }
    }

    // MARK: - ColorSpec vs. colorspec-cases.json

    @Test func colorSpecMatchesFixtureForAllPhotos() throws {
        guard let dcp = loadRealDCP() else { return }
        let fx = try loadFixture("colorspec-cases.json", as: ColorSpecCasesFixtureFile.self)

        guard let cm1 = dcp.colorMatrix1, let cm2 = dcp.colorMatrix2,
              let illum1 = dcp.calibrationIlluminant1, let illum2 = dcp.calibrationIlluminant2
        else {
            Issue.record("DCPにColorMatrix/CalibrationIlluminantがありません")
            return
        }
        let spec = try ColorSpec(
            colorMatrix1: cm1, colorMatrix2: cm2,
            forwardMatrix1: dcp.forwardMatrix1, forwardMatrix2: dcp.forwardMatrix2,
            calibrationIlluminant1: illum1, calibrationIlluminant2: illum2
        )

        #expect(!fx.photos.isEmpty)
        for (name, photo) in fx.photos {
            let neutralG1 = SIMD3(
                photo.neutral_g1_normalized_rgb[0], photo.neutral_g1_normalized_rgb[1], photo.neutral_g1_normalized_rgb[2]
            )
            let whiteXY = try spec.neutralToXY(neutralG1)
            expectApproxEqual(whiteXY.x, photo.white_xy[0], relTol: 1e-4, absTol: 1e-7, "\(name) white.x")
            expectApproxEqual(whiteXY.y, photo.white_xy[1], relTol: 1e-4, absTol: 1e-7, "\(name) white.y")

            let temperature = DNGTemperature.xyToTemperature(whiteXY)
            expectApproxEqual(temperature, photo.cct_kelvin, relTol: 1e-4, absTol: 1e-3, "\(name) CCT")

            let g = spec.gFraction(white: whiteXY)
            expectApproxEqual(g, photo.g_fraction_stdA_weight, relTol: 1e-4, absTol: 1e-7, "\(name) gFraction")

            let colorMatrixWhite = spec.colorMatrix(white: whiteXY)
            expectMatrixApproxEqual(
                colorMatrixWhite, photo.color_matrix_interpolated_xyz_to_camera, "\(name) colorMatrix"
            )

            let forward = try spec.forwardMatrix(white: whiteXY)
            expectMatrixApproxEqual(
                forward, photo.forward_matrix_interpolated_camera_to_xyzd50, "\(name) forwardMatrix"
            )

            let cameraWhite = AdobeColorSpec.cameraWhite(colorMatrix: colorMatrixWhite, white: whiteXY)
            expectVectorApproxEqual(
                cameraWhite, photo.camera_white_sdk, relTol: 1e-4, absTol: 1e-6, "\(name) cameraWhite"
            )

            let combinedPrototype = try AdobeColorSpec.combinedCameraToLinearProPhoto(
                spec: spec, white: whiteXY, neutralG1: neutralG1, variant: .matchPrototype
            )
            expectMatrixApproxEqual(
                combinedPrototype, photo.combined_matrix_camera_to_linear_prophoto.match_prototype,
                "\(name) combined.matchPrototype"
            )

            let combinedSDK = try AdobeColorSpec.combinedCameraToLinearProPhoto(
                spec: spec, white: whiteXY, neutralG1: neutralG1, variant: .sdkCameraWhite
            )
            expectMatrixApproxEqual(
                combinedSDK, photo.combined_matrix_camera_to_linear_prophoto.sdk_camera_white,
                "\(name) combined.sdkCameraWhite"
            )
        }
    }

    // MARK: - AdobeColorMath vs. stage-samples.json

    @Test func stageSamplesMatchPythonReference() throws {
        guard let dcp = loadRealDCP(), let look = loadRealAdobeLook() else { return }
        let stageFx = try loadFixture("stage-samples.json", as: StageSamplesFixtureFile.self)
        let colorSpecFx = try loadFixture("colorspec-cases.json", as: ColorSpecCasesFixtureFile.self)

        #expect(stageFx.colorimetry_photo == "P1013558")
        guard let photo = colorSpecFx.photos[stageFx.colorimetry_photo] else {
            Issue.record("colorspec-cases.jsonに\(stageFx.colorimetry_photo)がありません")
            return
        }
        let neutralG1 = SIMD3(
            photo.neutral_g1_normalized_rgb[0], photo.neutral_g1_normalized_rgb[1], photo.neutral_g1_normalized_rgb[2]
        )

        // stage-samples.json's M/H/E/... were generated against the
        // prototype's own combined matrix (no SDK camera-white
        // correction), so this specific fixture requires `.matchPrototype`
        // to line up; `colorSpecMatchesFixtureForAllPhotos` above already
        // separately validates `.sdkCameraWhite`.
        // The fixture was generated with the prototype's +0.057 EV; the
        // production calibration table has since moved to 0, so pin the
        // fixture's own value here instead of the table's.
        let assets = try AdobeBaseAssets(
            dcp: dcp, look: look, neutralG1: neutralG1, variant: .matchPrototype, baselineEV: stageFx.baseline_ev
        )
        expectApproxEqual(assets.baselineEV, stageFx.baseline_ev, relTol: 1e-9, absTol: 1e-12, "baselineEV")

        for (index, sample) in stageFx.samples.enumerated() {
            let input = SIMD3(sample.input[0], sample.input[1], sample.input[2])
            let tag = "sample[\(index)]"

            expectVectorApproxEqual(
                AdobeColorMath.evaluate(cameraRGB: input, through: .matrix, assets: assets), sample.M, "\(tag) M"
            )
            expectVectorApproxEqual(
                AdobeColorMath.evaluate(cameraRGB: input, through: .hueSat, assets: assets), sample.H, "\(tag) H"
            )
            expectVectorApproxEqual(
                AdobeColorMath.evaluate(cameraRGB: input, through: .exposure, assets: assets), sample.E, "\(tag) E"
            )
            expectVectorApproxEqual(
                AdobeColorMath.evaluate(cameraRGB: input, through: .lookDCP, assets: assets), sample.L_dcp, "\(tag) L_dcp"
            )
            expectVectorApproxEqual(
                AdobeColorMath.evaluate(cameraRGB: input, through: .lookAdobe, assets: assets), sample.L_adobe, "\(tag) L_adobe"
            )
            expectVectorApproxEqual(
                AdobeColorMath.evaluate(cameraRGB: input, through: .acr3Tone, assets: assets), sample.T, "\(tag) T"
            )
            expectVectorApproxEqual(
                AdobeColorMath.evaluate(cameraRGB: input, through: .lookToneCurve(.a), assets: assets), sample.C_a, "\(tag) C_a"
            )
            expectVectorApproxEqual(
                AdobeColorMath.evaluate(cameraRGB: input, through: .lookToneCurve(.b), assets: assets), sample.C_b, "\(tag) C_b"
            )
            expectVectorApproxEqual(
                AdobeColorMath.evaluate(cameraRGB: input, through: .lookToneCurve(.c), assets: assets), sample.C_c, "\(tag) C_c"
            )

            let final = AdobeColorMath.evaluate(cameraRGB: input, through: .final, assets: assets)
            let clipped = SIMD3(min(max(final.x, 0), 1), min(max(final.y, 0), 1), min(max(final.z, 0), 1))
            let encoded = SIMD3(
                DNGColorSpace.srgbEncode(clipped.x), DNGColorSpace.srgbEncode(clipped.y), DNGColorSpace.srgbEncode(clipped.z)
            )
            let quantized = [encoded.x, encoded.y, encoded.z].map { min(max(Int(($0 * 255.0).rounded()), 0), 255) }
            #expect(quantized == sample.final_srgb8_variant_b, "\(tag) final_srgb8")
        }
    }

    // MARK: - ACR3DefaultToneCurve vs. acr3-default-curve.json

    @Test func acr3TableMatchesFixtureMD5AndSamples() throws {
        let fx = try loadFixture("acr3-default-curve.json", as: ACR3FixtureFile.self)
        #expect(ACR3DefaultToneCurve.table.count == fx.count)

        var bytes = [UInt8]()
        bytes.reserveCapacity(ACR3DefaultToneCurve.table.count * 4)
        for value in ACR3DefaultToneCurve.table {
            let bits = Float(value).bitPattern.littleEndian
            withUnsafeBytes(of: bits) { bytes.append(contentsOf: $0) }
        }
        let digestHex = Insecure.MD5.hash(data: Data(bytes)).map { String(format: "%02x", $0) }.joined()
        #expect(digestHex.caseInsensitiveCompare(fx.md5) == .orderedSame)

        for (indexString, expectedValue) in fx.samples {
            guard let index = Int(indexString) else { continue }
            expectApproxEqual(ACR3DefaultToneCurve.table[index], expectedValue, relTol: 1e-6, absTol: 1e-9, "acr3[\(index)]")
        }
    }

