    // MARK: - Property tests (no external asset needed)

    @Test func identityHueSatMapPreservesInputIn2Point5DTable() {
        let dims = DCPProfile.Dimensions3(hue: 4, sat: 4, val: 1)
        let entries = [DCPProfile.HueSatEntry](
            repeating: DCPProfile.HueSatEntry(hueShift: 0, satScale: 1, valScale: 1), count: 4 * 4 * 1
        )
        let table = DCPProfile.HueSatTable(dims: dims, entries: entries)

        for sample in identityTestSamples {
            let output = HueSatMap.apply(sample, table: table)
            expectVectorApproxEqual(output, [sample.x, sample.y, sample.z], relTol: 1e-9, absTol: 1e-9, "identity2.5D")
        }
    }

    @Test func identityHueSatMapPreservesInputInFullTrilinearTable() {
        let dims = DCPProfile.Dimensions3(hue: 4, sat: 4, val: 3)
        let entries = [DCPProfile.HueSatEntry](
            repeating: DCPProfile.HueSatEntry(hueShift: 0, satScale: 1, valScale: 1), count: 4 * 4 * 3
        )
        let table = DCPProfile.HueSatTable(dims: dims, entries: entries)

        for sample in identityTestSamples {
            let output = HueSatMap.apply(sample, table: table)
            expectVectorApproxEqual(output, [sample.x, sample.y, sample.z], relTol: 1e-9, absTol: 1e-9, "identityTrilinear")
        }
    }

    private var identityTestSamples: [SIMD3<Double>] {
        [
            SIMD3(0.8, 0.3, 0.1), SIMD3(0.1, 0.9, 0.4), SIMD3(0.5, 0.5, 0.5),
            SIMD3(0.0, 0.0, 0.0), SIMD3(1.0, 0.0, 0.0), SIMD3(0.2, 0.2, 0.9),
        ]
    }

    @Test func hueSatMapInterpolatedReturnsEndpointTablesAtExtremes() throws {
        let dims = DCPProfile.Dimensions3(hue: 2, sat: 2, val: 1)
        let table1 = DCPProfile.HueSatTable(dims: dims, entries: [
            .init(hueShift: 10, satScale: 1, valScale: 1), .init(hueShift: 10, satScale: 1, valScale: 1),
            .init(hueShift: 10, satScale: 1, valScale: 1), .init(hueShift: 10, satScale: 1, valScale: 1),
        ])
        let table2 = DCPProfile.HueSatTable(dims: dims, entries: [
            .init(hueShift: -10, satScale: 1, valScale: 1), .init(hueShift: -10, satScale: 1, valScale: 1),
            .init(hueShift: -10, satScale: 1, valScale: 1), .init(hueShift: -10, satScale: 1, valScale: 1),
        ])
        let atOne = try HueSatMap.interpolated(table1, table2, g: 1.0)
        #expect(atOne.entries[0].hueShift == 10)
        let atZero = try HueSatMap.interpolated(table1, table2, g: 0.0)
        #expect(atZero.entries[0].hueShift == -10)
        let atHalf = try HueSatMap.interpolated(table1, table2, g: 0.5)
        expectApproxEqual(atHalf.entries[0].hueShift, 0, absTol: 1e-9, "interpolated midpoint")

        let mismatched = DCPProfile.HueSatTable(
            dims: DCPProfile.Dimensions3(hue: 3, sat: 2, val: 1), entries: Array(repeating: table1.entries[0], count: 6)
        )
        #expect(throws: HueSatMapError.self) {
            _ = try HueSatMap.interpolated(table1, mismatched, g: 0.5)
        }
    }

    @Test func rgbTonePreservesHue() {
        let samples: [SIMD3<Double>] = [
            SIMD3(0.8, 0.3, 0.1), SIMD3(0.2, 0.6, 0.9), SIMD3(0.9, 0.9, 0.2),
            SIMD3(0.9, 0.2, 0.9), SIMD3(0.1, 0.7, 0.7), SIMD3(0.7, 0.7, 0.1),
        ]
        for sample in samples {
            let (hueBefore, satBefore, _) = HueSatMap.rgbToHSV(sample)
            let toned = RGBTone.apply(sample, curve: ACR3DefaultToneCurve.evaluate)
            guard satBefore > 1e-9 else { continue } // hue is undefined (0) for neutral pixels
            let (hueAfter, _, _) = HueSatMap.rgbToHSV(toned)
            expectApproxEqual(hueAfter, hueBefore, relTol: 1e-6, absTol: 1e-6, "hue preserved")
        }
    }

    @Test func rgbToneDegenerateGrayInputDoesNotDivideByZero() {
        let gray = SIMD3(0.5, 0.5, 0.5)
        let toned = RGBTone.apply(gray, curve: ACR3DefaultToneCurve.evaluate)
        let expected = ACR3DefaultToneCurve.evaluate(0.5)
        expectVectorApproxEqual(toned, [expected, expected, expected], relTol: 1e-9, absTol: 1e-9, "gray tone")
    }

    @Test func identitySplineIsIdentityAndUsesFlatExtension() throws {
        let spline = try DNGSpline(points: [(x: 0.0, y: 0.0), (x: 1.0, y: 1.0)])
        for x in stride(from: 0.0, through: 1.0, by: 0.1) {
            expectApproxEqual(spline.evaluate(x), x, relTol: 1e-9, absTol: 1e-9, "identity spline")
        }
        #expect(spline.evaluate(-0.5) == 0.0)
        #expect(spline.evaluate(1.5) == 1.0)
    }

    @Test func splineRejectsDegenerateInput() {
        #expect(throws: RGBToneError.self) {
            _ = try DNGSpline(points: [(x: 0.0, y: 0.0)])
        }
        #expect(throws: RGBToneError.self) {
            _ = try DNGSpline(points: [(x: 0.5, y: 0.0), (x: 0.5, y: 1.0)])
        }
    }

    @Test func base85DecodeKnownVectors() {
        #expect(AdobeLookXMP.decodeBase85ish("00000") == [0, 0, 0, 0])
        #expect(AdobeLookXMP.decodeBase85ish("00001") == [177, 132, 28, 3])
        #expect(AdobeLookXMP.decodeBase85ish("11111") == [45, 0, 38, 3])
        #expect(AdobeLookXMP.decodeBase85ish("0000") == [0, 0, 0]) // 4-char remainder -> 3 bytes
        #expect(AdobeLookXMP.decodeBase85ish("000") == [0, 0]) // 3-char remainder -> 2 bytes
        #expect(AdobeLookXMP.decodeBase85ish("00") == [0]) // 2-char remainder -> 1 byte
        #expect(AdobeLookXMP.decodeBase85ish("0") == []) // lone leftover char -> dropped
        #expect(AdobeLookXMP.decodeBase85ish("0 0\n001") == [177, 132, 28, 3]) // whitespace ignored
        #expect(AdobeLookXMP.decodeBase85ish("vqf00") == [24, 176, 1, 0]) // real Adobe Color.xmp blob prefix
    }

    @Test func dcpProfileRejectsWrongMagic() {
        // Standard TIFF magic (0x002A) rather than DCP's private "RC" marker.
        var bytes: [UInt8] = [0x49, 0x49, 0x2A, 0x00, 8, 0, 0, 0]
        bytes.append(contentsOf: [0, 0]) // IFD entry count = 0, at offset 8
        #expect(throws: DCPProfileError.self) {
            _ = try DCPProfile(data: Data(bytes))
        }
    }

    @Test func adobeBaseCalibrationKnownAndUnknownModels() {
        expectApproxEqual(
            AdobeBaseCalibration.baselineEV(uniqueCameraModel: "Panasonic DC-S5"), 0.0,
            relTol: 1e-9, absTol: 1e-12, "DC-S5 baselineEV"
        )
        #expect(AdobeBaseCalibration.baselineEV(uniqueCameraModel: "Some Unknown Camera") == 0.0)
    }
}

// MARK: - Fixture JSON shapes (test-only Decodable mirrors of Tests/Fixtures/phase1/*.json)

private struct HueSatSampleFixture: Decodable {
    let val_index: Int
    let hue_index: Int
    let sat_index: Int
    let hue_shift: Double
    let sat_scale: Double
    let val_scale: Double
}

private struct DCPFixtureFile: Decodable {
    let unique_camera_model: String
    let profile_name: String
